# Parse the note lines into desired quantities and descriptions
import re
content = None
if 'note' in globals():
    content = note.get('content')

if content is None:
    raise SystemExit('No note content available')

items = []
for line in content.splitlines():
    line=line.strip()
    if not line:
        continue
    m = re.match(r'^[-*]\s*(\d+)\s+quantity of\s+(.+)$', line, flags=re.IGNORECASE)
    if m:
        qty = int(m.group(1))
        desc = m.group(2).strip()
        items.append({'desired_qty': qty, 'description': desc})
    else:
        # fallback: try to match '- <n> quantity of <desc>' without 'quantity of'
        m2 = re.match(r'^[-*]\s*(\d+)\s+quantity\s+of\s+(.+)$', line, flags=re.IGNORECASE)
        if m2:
            qty=int(m2.group(1)); desc=m2.group(2).strip()
            items.append({'desired_qty': qty, 'description': desc})

print('parsed_items', items)
print('num_items', len(items))

